    {
      "id": 1,
      "claim": "U.S. federal law does not require employers to provide health benefits or equal pay to temporary workers.",
      "evidence": "The Fair Labor Standards Act sets minimum wage and overtime rules but contains no provision mandating benefit parity or equal pay for temps; the Equal Pay Act addresses gender discrimination, not employment status.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Therefore, options C (must be offered health care and other benefits) and D (must be paid equal to full‑time employees) are false.",
      "evidence": "Since no legal requirement exists per step 1, those statements cannot be universally true.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "There is no general legal rule limiting a temporary assignment to 30 days before a permanent offer must be made.",
      "evidence": "No federal statute imposes a 30‑day limit; temporary assignments can last weeks, months, or be project‑based without a conversion requirement.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 4,
      "claim": "A key practical consideration when hiring temporary workers is that they are often less experienced and less committed to the organization than full‑time employees.",
      "evidence": "HR sources such as the Society for Human Resource Management (SHRM) note higher turnover rates, lower organizational commitment, and the need for additional training when using temps, especially for non‑specialized roles.",
      "weight": 0.35,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "By eliminating the false options (B, C, D) and recognizing the practical HR concern in step 4, the correct completion is option A.",
      "evidence": "Logical elimination based on steps 2, 3, 4.",
      "weight": 0.15,
      "depends_on": [2, 3, 4]
    }
  ],
  "answer": "A",
  "confidence": 0.93,
  "considered": [
    {
      "answer": "B",
      "reason_rejected": "No statutory 30‑day limit exists for temporary workers."
    },
    {
      "answer": "C",
      "reason_rejected": "Benefits are not universally required for temps under federal law."
    },
    {
      "answer": "D",
      "reason_rejected": "Equal‑pay requirements apply to gender discrimination, not to employment status; no universal mandate for temps to receive the same pay as full‑time employees."
    }
  ]
